# Gabriel Sagard, Le Grand Voyage du pays des Hurons (1632), suivi du Dictionnaire de la langue huronne, éd. critique
# de Jack Warwick, Montréal, Presses de l'Université de Montréal, coll. « Bibliothèque du Nouveau Monde », 1998.
# PDF du Drive de l'auteur (HISTOIRE_LIVRES/AUTOCHTONES), lu le 19 novembre 2026 : itinéraire de 1623-1624, séjour en Huronie
# et annotations de Warwick. Préfixe SG32 ; pages de l'édition Warwick.
from commun import Corpus
S = "Sagard, Gabriel (1632), Le Grand Voyage du pays des Hurons, éd. Jack Warwick, Montréal, Presses de l'Université de Montréal, 1998"
C = Corpus('Recherches', 'SG32', S, page_fmt='p. {}')
F = C.F
P = ['Gabriel Sagard']
F('01', "Gaspé : escale du récollet Sagard en route vers les Hurons (juin 1623)", 'exploration', '1623-06', -64.48, 48.83, 'c', P + ['Nicolas Viel'],
  "Parti de Paris à pied le 18 mars 1623 avec le père Nicolas Viel, Sagard s'embarque à Dieppe ; la traversée dure cent trois jours. À Gaspé, où le grand vaisseau reste au port, il se promène sur les hautes montagnes pour contempler l'embouchure du Saint-Laurent, voit homards, truites, levrauts et perdrix, puis passe dans la pinasse la Magdeleine pour gagner Tadoussac en longeant les monts Notre-Dame encore enneigés.",
  '117, 135-137', "Le texte imprimé porte 1624 ; Warwick corrige en 1623.")
F('02', "Tadoussac, pointe aux Vaches : le village fortifié des Montagnais visité par Sagard (1623)", 'rencontre', '1623-06', -69.71, 48.14, 'c', P + ['François Gravé du Pont', 'Nicolas Marsolet'],
  "À la rade de Tadoussac, sur le haut de la pointe aux Vaches, se dresse un village de « Canadiens » (Montagnais) fortifié à la manière huronne. Pendant que le navire attend la marée, Sagard descend visiter les cabanes. Il décrit le petit port, où ne tiennent que vingt ou vingt-cinq vaisseaux, d'où des barques portent les marchandises à Québec, et rapporte comment Gravé du Pont faillit s'y perdre. Un groupe de Français s'y trouve, dont Nicolas Marsolet.",
  '139-141', "")
F('03', "Québec, rivière Saint-Charles : le petit couvent des Récollets (1620-1623)", 'religion', '1620/1623', -71.235, 46.82, 'c', P + ['Joseph Le Caron', 'Samuel de Champlain'],
  "Les Récollets, arrivés avec Champlain en 1615, mettent en chantier en 1619 un couvent sur la rivière Saint-Charles, dont la première pierre est posée en 1620 ; ils gardent aussi la chapelle de Québec. En 1623, Sagard et ses compagnons s'y reposent deux ou trois jours avant de remonter le fleuve avec les barques de la traite. Sagard décrit l'habitation de Champlain et la ferme où l'on élève du bétail venu de France et sème du maïs et des pois.",
  '85, 145-147', "")
F('04', "Cap de Victoire (Onthrandéen), près de Sorel : la traite de 1623 et le départ avec les Hurons (22 juillet 1623)", 'commerce', '1623-07-22', -73.0, 46.07, 'c', P + ['Joseph Le Caron', 'Nicolas Viel'],
  "Les barques remontent par Sainte-Croix, les Trois-Rivières et le lac Saint-Pierre jusqu'au cap de Victoire, que les Hurons appellent Onthrandéen et où se tient la traite entre Français et nations diverses ; on y arrive le jour de la Sainte-Madeleine. Les Hurons, contre quelques présents, acceptent d'emmener chez eux les pères Joseph Le Caron et Nicolas Viel et le frère Sagard. Le nom de Victoire, ou de Massacre, rappelle peut-être la défaite d'Iroquois par des Algonquins aidés de Champlain en 1610.",
  '148-149', "")
F('05', "Baie Georgienne : deux jours de traite chez les Cheveux-Relevés (août 1623)", 'rencontre', '1623-08', -80.6, 45.95, 'h', P,
  "Avant d'atteindre la Huronie, le canot de Sagard s'arrête deux jours chez les Cheveux-Relevés (Outaouais), venus s'établir près de la mer douce pour commercer avec les Hurons qui reviennent de la traite de Québec. Sagard décrit leurs cheveux dressés sur le front « plus droits que les perruques des dames », tenus par un fer ou une hache chaude.",
  '158', "Point hypothétique près de l'embouchure de la rivière des Français.")
F('06', "Ossossané (Tequenonquiaye, « La Rochelle ») : arrivée de Sagard en Huronie et son adoption (20 août 1623)", 'rencontre', '1623-08-20', -79.97, 44.65, 'a', P,
  "Après avoir traversé la mer douce d'île en île, Sagard prend terre en Huronie le dimanche de la Saint-Bernard, vers midi, du côté de Penetanguishene, et traverse la péninsule à pied. Il est accueilli comme parent dans une famille du bourg, probablement Tequenonquiaye, ville principale des Ours, que des Français appelaient La Rochelle, les Récollets Saint-Gabriel et les Jésuites Ossossané : la mère l'appelle « mon fils », les autres « mon frère », « mon neveu » ou « mon oncle ».",
  '161-162', "Identification du bourg d'après Warwick.")
F('07', "Quieunonascaran : la cabane des Récollets, Le Caron, Viel et Sagard chez le grand capitaine Auoindaon (1623-1624)", 'religion', '1623-09/1624-05', -79.88, 44.78, 'h', P + ['Joseph Le Caron', 'Nicolas Viel', 'Auoindaon', 'Onorotandi'],
  "Sagard rejoint le père Le Caron au bourg de Quieunonascaran, siège du grand capitaine de la nation des Ours, Auoindaon ; les trois religieux s'y font bâtir une cabane. Faute de vin de messe, ils en font avec le raisin sauvage, pressé dans leur mortier de bois avec une serviette de chapelle, et en tirent aussi du raisiné. L'hiver, ils vont chercher du bois en raquettes. Sagard note qu'il faut la permission d'Onorotandi, frère d'Auoindaon, pour aller au Saguenay, et celle d'Auoindaon pour descendre à Québec.",
  '166-167, 173-174, 187, 231', "Emplacement discuté (baie de Midland ou face à l'île Christian) ; point hypothétique.")
F('08', "Toenchain (bourg de Saint-Nicolas) : la mission du père Nicolas Viel et le Français voleur de rassade (1623-1624)", 'religion', '1623/1624', -79.93, 44.79, 'h', ['Nicolas Viel', 'Gabriel Sagard'],
  "Le père Nicolas Viel s'installe à Toenchain, « la bourgade de Saint-Nicolas », à cinq lieues du village où Sagard a d'abord logé. Un Français qui y avait volé de la rassade s'enfuit dans la cabane des Récollets quand il voit arriver chez lui le devin (oki) chargé de découvrir le voleur. Au retour de 1624, Étienne Brûlé descend avec cinq ou six canots de Toenchain.",
  '165-166, 225, 319', "")
F('09', "Île de la baie Georgienne : Sagard à la pêche de l'assihendo avec Auoindaon (octobre 1623)", 'rencontre', '1623-10', -80.15, 45.05, 'h', P + ['Auoindaon'],
  "En octobre, Sagard part de Quieunonascaran avec le capitaine Auoindaon, à cinq dans un petit canot, vers le nord de la mer douce, jusqu'à une île où plusieurs ménages pêchent l'assihendo (corégone). Il décrit les festins et les cérémonies de la pêche, les esturgeons et truites « monstrueusement grands », et sonde quarante-huit brasses d'eau. Une fausse nouvelle de la mort du père Viel le fait rentrer précipitamment.",
  '261-267', "Île non identifiée ; point hypothétique.")
F('10', "Lac Nipissing : retour de Sagard avec Brûlé et les canots hurons (printemps 1624)", 'exploration', '1624-05/1624-06', -79.4, 46.3, 'a', P + ['Étienne Brûlé', 'Andatayon'],
  "Rappelé en France, Sagard redescend en 1624 avec les Hurons. En chemin, il rejoint Étienne Brûlé et cinq ou six canots de Toenchain et mange l'esturgeon dans un village algonquin. Il campe à l'entrée de la rivière des Français, traverse le lac des Épicerinys (Nipissing), traite un esturgeon contre un petit couteau dans un village nipissingue et voit ses Hurons afficher sur un pin les « armoiries » de Quieunonascaran, un canot dessiné sur une écorce de bouleau. Il passe ensuite la chute des Paresseux et le confluent de la Mattawa.",
  '318-325', "")
F('11', "Saut de la Chaudière (Asticou, Anoô) : Sagard décrit les chutes et celles du Rideau (1624)", 'exploration', '1624-06', -75.72, 45.42, 'c', P + ['Étienne Brûlé', 'La Montagne'],
  "Le saut de la Chaudière, sur l'Outaouais, est « le plus admirable, le plus dangereux et le plus épouvantable » de tous : large de plus d'un quart de lieue, coupé d'îlots rocheux, avec deux grands bassins tourbillonnants d'où monte la poussière d'eau, et dont le bruit s'entend à deux lieues ; Montagnais et Hurons l'appellent Asticou et Anoô, « chaudière ». Un quart de lieue plus loin, les chutes du Rideau tombent en deux arcades derrière lesquelles les jeunes Indiens passent en canot. Quelques heures plus tôt, un Français nommé La Montagne a failli se perdre dans une chute avec ses Sauvages. C'est là aussi que Brûlé avait participé à la cérémonie du tabac.",
  '330-332', "")
F('12', "Petite Nation (Weskarinis) : les veuves de l'hiver et le chien acheté par Brûlé (1624)", 'rencontre', '1624-06', -75.1, 45.6, 'h', P + ['Étienne Brûlé'],
  "À la Petite Nation, les députés du village demandent aux Hurons d'« essuyer les larmes » de vingt-cinq ou trente veuves dont les maris sont morts de faim ou de maladie l'hiver passé ; Sagard les convainc de faire un présent de maïs et de farine. Brûlé, campé avec eux, achète un chien dont on fait festin. Des Algonquins répandent le bruit que les navires de France ont péri, pour décourager les Hurons de descendre à la traite.",
  '332-333', "Point hypothétique dans la région de Montebello.")
F('13', "Saut Saint-Louis et cap de Victoire : le canot brisé et la ruse des Montagnais (juin-juillet 1624)", 'commerce', '1624-06/1624-07', -73.6, 45.42, 'c', P + ['Étienne Brûlé'],
  "Au saut Saint-Louis, Sagard, resté seul dans le canot que ses Sauvages guident à la main, saute sur une roche juste avant que l'embarcation tombe dans un précipice ; ils la retirent à demi brisée avec une longue corde et la réparent. Au cap de Victoire, où Brûlé est arrivé deux jours plus tôt, Montagnais et Algonquins veulent retenir les Hurons et font courir le bruit qu'ils ont reçu vingt colliers des Agniers pour les faire massacrer ; les Hurons se cotisent pour les apaiser, sauf ceux de Sagard.",
  '334-335', "Point au saut Saint-Louis (rapides de Lachine).")
F('14', "Rivière des Prairies (Sault-au-Récollet) : la noyade du père Nicolas Viel et de son disciple Auhaitsique (1625)", 'evenement', '1625', -73.66, 45.58, 'c', ['Nicolas Viel', 'Auhaitsique'],
  "Redescendant de la Huronie en 1625, le récollet Nicolas Viel se noie dans le dernier rapide de la rivière des Prairies avec son disciple français surnommé Auhaitsique ; le lieu prendra le nom de Sault-au-Récollet. Warwick note que la noyade n'était pas encore attribuée à un crime quand Sagard écrivit le Grand Voyage ; en 1634, pour effrayer les Jésuites, le chef algonquin Tessouat accuse les Hurons d'avoir tué Viel et Brûlé.",
  '25-26, 89, 323', "D'après l'introduction et les notes de Warwick.")
fiches = C.fiches
